import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { textContent, assets, scenePosition, sceneRotation, sceneScale } = config;

  // ── Root group ────────────────────────────────────────────────
  const group = new THREE.Group();
  group.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  group.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  group.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // ── Load texture ──────────────────────────────────────────────
  const texture = ctx.textureLoader.load(assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // ── Plane geometry (matching source rect aspect: 512/320 ≈ 1.6) ──
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  // ── Material ──────────────────────────────────────────────────
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    depthWrite: true,
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // ── Text overlay (headline) ───────────────────────────────────
  if (textContent && textContent.length > 0) {
    const textSpec = textContent[0]; // "Features 1"
    const textMesh = ctx.fontAtlas.createText({
      text: textSpec.content,
      font: 'display',       // Lora serif
      weight: 400,
      fontSize: 0.34,        // scene-unit em height for headline
      align: 'center',
      materialType: 'MeshBasicNodeMaterial',
      color: '#e8ecf2',      // paper color for contrast (#e8ecf2 on machined metal?)
      // Use the token paper: '#e8ecf2'
    });
    textMesh.position.set(0, 0, 0.01); // slightly in front of plane
    group.add(textMesh);
  }

  // ── Event handlers (none) ─────────────────────────────────────
  group.userData.handlers = {};

  // ── Cleanup ───────────────────────────────────────────────────
  group.userData.cleanup = () => {
    // Kill any GSAP timelines (none in this node)
    // Dispose geometry, material, texture
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Dispose text mesh if present
    if (group.children.length > 1) {
      const textChild = group.children[1];
      if (textChild.geometry) textChild.geometry.dispose();
      if (textChild.material) textChild.material.dispose();
    }
  };

  return group;
}
